total = 0
for g in goods:
    if g.price >= 3:
        total += g.price
print(total)

class Account:
    def __init__(self, money):
        self.money = money
    def take(self, x):
        if x > self.money:
            return False
        self.money -= x
        return True
a = Account(100)
print(a.take(30), a.take(80), a.money)

