class Word:
    def __init__(self, s):
        self.s = s
    def count_vowel(self):
        k = 0
        for ch in self.s:
            if ch in 'aeiou':
                k += 1
        return k
print(Word('education').count_vowel())

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def dist2(self, other):
        return (self.x - other.x) ** 2 + (self.y - other.y) ** 2
p = Point(1, 2)
q = Point(4, 6)
print(p.dist2(q), q.dist2(p))
